import {DmsUploadDropzone,type SelectedDmsFile} from '@/features/dms/upload/dms-upload-dropzone';
import {useDmsBatchAdmission} from '@/hooks/use-dms-batch-admission';
import {DmsUploadInboxPageClient} from '@/features/dms/upload/dms-upload-inbox-page-client';
const originalCrypto = Object.getOwnPropertyDescriptor(globalThis,'crypto');
const auth='11111111-1111-4111-8111-111111111111',operation='22222222-2222-4222-8222-222222222222';
const code='A'.repeat(32),batchCode='B'+'B'.repeat(32);
const snapshot:BatchDraftSnapshot={upload_session_id:17,session_code:code,batch_id:18,analysis_result_id:19,owning_company_id:20,owning_branch_id:21,party_id:null,document_type_id:22,category_id:23,title:'Original',description:null,confidentiality_level:'internal',issue_date:null,expiry_date:null,confidence:'high',source_fingerprint:'a'.repeat(64)};
let receipt:BatchReceipt;
let sealed=false;
function receiptFor(r:BatchRequest):BatchReceipt{return {version:1,operation_id:r.contract.operationId,auth_user_id:auth,profile_id:7,fingerprint:createHash('sha256').update(JSON.stringify(['dms-batch-admission/v1',null,r.manifest.files.map(f=>[f.position,f.original_filename,f.mime_type,f.file_size_bytes,f.sha256_hash])])).digest('hex'),manifest:r.manifest,batch_id:18,batch_code:batchCode,company_id:20,branch_id:21,members:[{position:0,id:17,code,bucket:'dms-temp',path:'sessions/'+code+'/Synthetic.pdf',name:'Synthetic.pdf',mime:'application/pdf',size:1,sha256:r.manifest.files[0].sha256_hash}]};}
function member(prepared:boolean){return {position:0,upload_session_id:17,session_code:code,draft_operation_id:operation,kind:prepared?'prepared':'unprepared',request:{uploadSessionId:17,allowDuplicate:false,...(prepared?{prepared:snapshot}:{})}};}
function anchors(){return {version:1,admission_operation_id:receipt.operation_id,admission_fingerprint:receipt.fingerprint,auth_user_id:auth,profile_id:7,batch_id:18,owning_company_id:20,owning_branch_id:21};}
function prepared(){return {success:true,receipt,preparation:{...anchors(),member:member(true)}};}
const ui=()=> <DmsUploadInboxPageClient initialSessions={[]} documents={[]} documentTypes={[]} batchEnabled/>;
const select=async()=>{const file=new File(['x'],'Synthetic.pdf',{type:'application/pdf'});fireEvent.change(screen.getByLabelText('Choose document files'),{target:{files:[file]}});await waitFor(()=>expect(screen.getByRole('button',{name:'Upload & AI Fill All (1)'})).toBeTruthy());};
const start=async()=>{fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await select();await waitFor(()=>expect((screen.getByRole('button',{name:'Upload & AI Fill All (1)'}) as HTMLButtonElement).disabled).toBe(false));fireEvent.click(screen.getByRole('button',{name:'Upload & AI Fill All (1)'}));};
beforeEach(()=>{vi.resetAllMocks();Object.defineProperty(globalThis,'crypto',{configurable:true,value:webcrypto});m.store=createWorkspaceDraftStore();m.owner='owner';sealed=false;m.readOwner={identity:{authUserId:auth,scopeVersion:'scope'},generation:0,isLive:()=>true,admits:()=>true};m.bootstrap.mockResolvedValue({success:true,origin:{authUserId:auth,profileId:7}});m.batch.mockImplementation(async(r:BatchRequest)=>{if(!r.manifest)return {state:'rejected',error:'Invalid batch request'};receipt=receiptFor(r);return {state:'admitted',receipt,capabilityState:'unavailable',capabilities:[],presentPositions:[],issuance_may_be_partial:false};});m.read.mockImplementation(async()=>({success:true,receipt,recovery:{...anchors(),members:[member(sealed)]}}));m.member.mockImplementation(async()=>({state:'ready',receipt,position:0,object:{state:'upload',capability:{position:0,sessionId:17,path:receipt.members[0].path,token:'synthetic-test-value',signedUrl:'https://example.invalid/upload'}},issuance_may_be_partial:true}));m.verify.mockResolvedValue({state:'present'});m.prepare.mockImplementation(async()=>{sealed=true;return prepared();});m.upload.mockResolvedValue({error:null});m.draft.mockImplementation(async(_i:BatchDraftInput,c:WorkspaceSaveContract)=>({success:true,data:{documentId:42,documentNo:'DMS-42',status:'pending_ai_review',confidence:'high',operation_id:c.operationId,upload_session_id:17,replayed:false}}));m.discover.mockResolvedValue({success:true,receipts:[]});});
afterEach(()=>{cleanup();vi.restoreAllMocks();if(originalCrypto)Object.defineProperty(globalThis,'crypto',originalCrypto);else Reflect.deleteProperty(globalThis,'crypto');});

it('pending independent bootstrap disables mutation',async()=>{m.bootstrap.mockImplementation(()=>new Promise(()=>{}));render(ui());fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await select();expect((screen.getByRole('button',{name:'Upload & AI Fill All (1)'}) as HTMLButtonElement).disabled).toBe(true);expect(m.batch).not.toHaveBeenCalled();});
it('bootstrap identity differing from the read owner fails closed',async()=>{m.bootstrap.mockResolvedValue({success:true,origin:{authUserId:'99999999-9999-4999-8999-999999999999',profileId:7}});render(ui());fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await select();await waitFor(()=>expect(screen.getByRole('alert').textContent).toMatch(/owner|identity/i));expect(m.batch).not.toHaveBeenCalled();});
it('unsupported entity context is rejected instead of becoming an unlinked batch',async()=>{render(<DmsUploadInboxPageClient initialSessions={[]} documents={[]} documentTypes={[]} batchEnabled entityContext={{entityType:'employee',entityId:9}}/>);fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await select();expect((screen.getByRole('button',{name:'Upload & AI Fill All (1)'}) as HTMLButtonElement).disabled).toBe(true);expect(screen.getByRole('alert').textContent).toMatch(/context/i);});
it('single-file mode does not bootstrap batch or change its callback',async()=>{const callback=vi.fn();render(<DmsUploadDropzone onFileSelected={callback}/>);const file=new File(['x'],'Synthetic.pdf',{type:'application/pdf'});fireEvent.change(screen.getByLabelText('Choose document file'),{target:{files:[file]}});await waitFor(()=>expect(callback).toHaveBeenCalledOnce());expect(callback.mock.calls[0][0].file).toBe(file);expect(m.bootstrap).not.toHaveBeenCalled();});
it.each(['','application/octet-stream'])('canonical batch MIME keeps original File for %s',async mime=>{const callback=vi.fn();render(<DmsUploadDropzone multiple onFilesSelected={callback}/>);const file=new File(['x'],'Synthetic.pdf',{type:mime});fireEvent.change(screen.getByLabelText('Choose document files'),{target:{files:[file]}});await waitFor(()=>expect(callback).toHaveBeenCalledOnce());expect(callback.mock.calls[0][0][0]).toMatchObject({mime_type:'application/pdf',file});expect(callback.mock.calls[0][0][0].file).toBe(file);});
it('a controlled empty selection clears the visible picker',async()=>{const callback=vi.fn(),file=new File(['x'],'Synthetic.pdf',{type:'application/pdf'});const f={original_filename:file.name,mime_type:file.type,file_size_bytes:1,sha256_hash:'a'.repeat(64),file};const h=render(<DmsUploadDropzone multiple files={[f]} onFilesSelected={callback}/>);expect(screen.getByRole('button',{name:'Remove Synthetic.pdf'})).toBeTruthy();h.rerender(<DmsUploadDropzone multiple files={[]} onFilesSelected={callback}/>);expect(screen.queryByRole('button',{name:'Remove Synthetic.pdf'})).toBeNull();});
it.each(['unmount','disable','owner'])('pending File read cannot publish after %s',async kind=>{const callback=vi.fn();let finish!:(v:ArrayBuffer)=>void;const file=new File(['x'],'Synthetic.pdf',{type:'application/pdf'});Object.defineProperty(file,'arrayBuffer',{value:()=>new Promise(r=>{finish=r;})});const h=render(<DmsUploadDropzone multiple ownerGeneration="A" onFilesSelected={callback}/>);fireEvent.change(screen.getByLabelText('Choose document files'),{target:{files:[file]}});if(kind==='unmount')h.unmount();else h.rerender(<DmsUploadDropzone multiple ownerGeneration={kind==='owner'?'B':'A'} disabled={kind==='disable'} onFilesSelected={callback}/>);await act(async()=>finish(new Uint8Array([120]).buffer));expect(callback).not.toHaveBeenCalled();});
it('confirmed admission continues through durable read despite capability issuance failure',async()=>{render(ui());await start();await waitFor(()=>expect(m.draft).toHaveBeenCalledOnce());expect(m.read).toHaveBeenCalledOnce();expect(m.member).toHaveBeenCalledOnce();expect(m.whole).not.toHaveBeenCalled();});
it('lost admission retains its operation and recovery uses read, not admit again',async()=>{m.batch.mockImplementationOnce(async(r:BatchRequest)=>{receipt=receiptFor(r);throw Error('PRIVATE token=secret');});render(ui());await start();await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));expect(document.body.textContent).not.toContain('PRIVATE');fireEvent.click(screen.getByRole('button',{name:'Recover retained batch'}));await waitFor(()=>expect(m.draft).toHaveBeenCalledOnce());expect(m.batch).toHaveBeenCalledOnce();expect(m.read.mock.calls[0][0]).toEqual(m.batch.mock.calls[0][0]);});
it('explicit discovery alone never runs provider or numbering; prepared reload needs no File',async()=>{const request:BatchRequest={manifest:{version:1,context:null,files:[{position:0,original_filename:'Synthetic.pdf',mime_type:'application/pdf',file_size_bytes:1,sha256_hash:'a'.repeat(64)}]},contract:{operationId:'33333333-3333-4333-8333-333333333333',revision:null}};receipt=receiptFor(request);sealed=true;m.discover.mockResolvedValue({success:true,receipts:[receipt]});render(ui());fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await waitFor(()=>expect((screen.getByRole('button',{name:'Find recent admissions'}) as HTMLButtonElement).disabled).toBe(false));fireEvent.click(screen.getByRole('button',{name:'Find recent admissions'}));await waitFor(()=>expect(screen.getByRole('button',{name:'Open admission '+batchCode})).toBeTruthy());expect(m.draft).not.toHaveBeenCalled();expect(m.ai).not.toHaveBeenCalled();expect(m.prepare).not.toHaveBeenCalled();fireEvent.click(screen.getByRole('button',{name:'Open admission '+batchCode}));await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));expect(m.draft).not.toHaveBeenCalled();fireEvent.click(screen.getByRole('button',{name:'Recover retained batch'}));await waitFor(()=>expect(m.draft).toHaveBeenCalledOnce());expect(m.member).not.toHaveBeenCalled();expect(m.upload).not.toHaveBeenCalled();expect(m.prepare).not.toHaveBeenCalled();expect(m.batch).not.toHaveBeenCalled();expect(m.ai).not.toHaveBeenCalled();});
it('prepared response with another origin cannot reach numbering',async()=>{m.prepare.mockImplementation(async()=>({...prepared(),preparation:{...prepared().preparation,auth_user_id:'99999999-9999-4999-8999-999999999999'}}));render(ui());await start();await waitFor(()=>expect(m.prepare).toHaveBeenCalledOnce());await waitFor(()=>expect(m.error).toHaveBeenCalled());expect(m.draft).not.toHaveBeenCalled();});
it('processing is an explicit stop, never an automatic provider retry',async()=>{m.prepare.mockImplementation(async()=>({success:true,receipt,preparation:{...anchors(),member:{...member(false),kind:'analysis_required',processing:true}}}));render(ui());await start();await waitFor(()=>expect(screen.getByText(/Analysis is already processing/)).toBeTruthy());expect(m.prepare).toHaveBeenCalledOnce();expect(m.draft).not.toHaveBeenCalled();expect(m.push).not.toHaveBeenCalled();});
it('actual inbox single mode leaves modern admission bootstrap inactive',async()=>{render(ui());await act(async()=>{});expect(screen.getByLabelText('Choose document file')).toBeTruthy();expect(m.bootstrap).not.toHaveBeenCalled();expect(m.batch).not.toHaveBeenCalled();expect(m.ai).not.toHaveBeenCalled();});
it('metadata request and actual Storage body use original bytes, canonical MIME and non-upsert target',async()=>{render(ui());await start();await waitFor(()=>expect(m.draft).toHaveBeenCalledOnce());const request=m.batch.mock.calls[0][0];expect(request.manifest).toEqual({version:1,context:null,files:[{position:0,original_filename:'Synthetic.pdf',mime_type:'application/pdf',file_size_bytes:1,sha256_hash:'2d711642b726b04401627ca9fbac32f5c8530fb1903cc4db02258717921a4881'}]});expect(request.contract).toEqual({operationId:expect.stringMatching(/^[0-9a-f-]{36}$/),revision:null});const [path,token,body,options]=m.upload.mock.calls[0];expect(path).toBe('sessions/'+code+'/Synthetic.pdf');expect(token).toBe('synthetic-test-value');expect(body.type).toBe('application/pdf');expect(Array.from(new Uint8Array(await body.arrayBuffer()))).toEqual([120]);expect(options).toEqual({contentType:'application/pdf',upsert:false});const store=m.store as ReturnType<typeof createWorkspaceDraftStore>;const persisted=JSON.stringify([store.getDraft('draft:tab:owner:f06-batch-admission:inbox:all'),store.getDraft('draft:tab:owner:f06-batch-drafts:inbox:all')]);for(const privateValue of ['synthetic-test-value','https://example.invalid','capabilities','signedUrl','[object File]'])expect(persisted).not.toContain(privateValue);expect(m.ai).not.toHaveBeenCalled();});
it.each(['admission','read','prepare','profile'])('self-consistent foreign %s remains denied by independently bootstrapped origin',async stage=>{const foreign='99999999-9999-4999-8999-999999999999';const foreignize=(r:BatchReceipt)=>({...r,...(stage==='profile'?{profile_id:99}:{auth_user_id:foreign})});if(stage==='admission')m.batch.mockImplementation(async(r:BatchRequest)=>{receipt=receiptFor(r);return {state:'admitted',receipt:foreignize(receipt),capabilityState:'unavailable',capabilities:[],presentPositions:[],issuance_may_be_partial:false};});else if(stage==='read'||stage==='profile')m.read.mockImplementation(async()=>({success:true,receipt:foreignize(receipt),recovery:{...anchors(),...(stage==='profile'?{profile_id:99}:{auth_user_id:foreign}),members:[member(false)]}}));else m.prepare.mockImplementation(async()=>({success:true,receipt:foreignize(receipt),preparation:{...anchors(),auth_user_id:foreign,member:member(true)}}));render(ui());await start();await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));expect(m.draft).not.toHaveBeenCalled();if(stage==='admission')expect(m.read).not.toHaveBeenCalled();if(stage==='read'||stage==='profile'){expect(m.member).not.toHaveBeenCalled();expect(m.prepare).not.toHaveBeenCalled();}expect(m.ai).not.toHaveBeenCalled();});
it.each(['rejected','unconfirmed'])('prepare %s stops without direct provider or consumer fallback',async status=>{m.prepare.mockResolvedValue({success:false,code:status,uncertain:status==='unconfirmed',error:'PRIVATE_DETAIL'});render(ui());await start();await waitFor(()=>expect(m.prepare).toHaveBeenCalledOnce());await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));expect(m.draft).not.toHaveBeenCalled();expect(m.ai).not.toHaveBeenCalled();expect(m.whole).not.toHaveBeenCalled();expect(document.body.textContent).not.toContain('PRIVATE_DETAIL');});
it('read rejection after admission transport loss retains the original immutable request across remount',async()=>{let beforeLoss!:BatchRequest;m.batch.mockImplementationOnce(async(r:BatchRequest)=>{beforeLoss=structuredClone(r);receipt=receiptFor(r);throw Error('lost');});const h=render(ui());await start();await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));m.read.mockResolvedValueOnce({success:false,code:'rejected',uncertain:false,error:'denied'});fireEvent.click(screen.getByRole('button',{name:'Recover retained batch'}));await waitFor(()=>expect(m.read).toHaveBeenCalledOnce());h.unmount();render(ui());fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));fireEvent.click(screen.getByRole('button',{name:'Recover retained batch'}));await waitFor(()=>expect(m.read).toHaveBeenCalledTimes(2));expect(m.read.mock.calls[0][0]).toEqual(beforeLoss);expect(m.read.mock.calls[1][0]).toEqual(beforeLoss);expect(m.batch).toHaveBeenCalledOnce();});
function retainedRequest():BatchRequest{return {manifest:{version:1,context:null,files:[{position:0,original_filename:'Synthetic.pdf',mime_type:'application/pdf',file_size_bytes:1,sha256_hash:'a'.repeat(64)}]},contract:{operationId:'33333333-3333-4333-8333-333333333333',revision:null}};}
function seedAdmission(preparedMember=false){receipt=receiptFor(retainedRequest());sealed=preparedMember;(m.store as ReturnType<typeof createWorkspaceDraftStore>).setDraft('draft:tab:owner:f06-batch-admission:inbox:all',{admission:JSON.stringify({request:retainedRequest(),origin:{authUserId:auth,profileId:7},uncertain:false,receipt})});}
async function recover(){fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));fireEvent.click(screen.getByRole('button',{name:'Recover retained batch'}));}
it('fresh-store sealed replay is exact and has no temporary-byte precondition',async()=>{seedAdmission(true);let finish!:(r:unknown)=>void;m.draft.mockImplementationOnce(()=>new Promise(r=>{finish=r;}));render(ui());await recover();await waitFor(()=>expect(m.draft).toHaveBeenCalledOnce());expect(m.draft.mock.calls[0]).toEqual([{uploadSessionId:17,allowDuplicate:false,prepared:snapshot},{operationId:operation,revision:null}]);for(const fn of [m.batch,m.member,m.verify,m.upload,m.prepare,m.whole,m.ai])expect(fn).not.toHaveBeenCalled();expect(m.push).not.toHaveBeenCalled();expect(m.success).not.toHaveBeenCalled();await act(async()=>finish({success:true,data:{documentId:42,documentNo:'DMS-42',status:'pending_ai_review',confidence:'high',operation_id:operation,upload_session_id:17,replayed:true}}));expect(m.success.mock.calls[0][0]).toMatch(/confirmed/);expect(m.success.mock.calls[0][0]).not.toMatch(/created/);});
it('unprepared verified-present recovery needs no selected File',async()=>{seedAdmission();m.member.mockImplementation(async()=>({state:'ready',receipt,position:0,object:{state:'present'},issuance_may_be_partial:false}));render(ui());await recover();await waitFor(()=>expect(m.draft).toHaveBeenCalledOnce());expect(m.upload).not.toHaveBeenCalled();expect(m.verify).toHaveBeenCalledOnce();expect(m.verify.mock.invocationCallOrder[0]).toBeLessThan(m.prepare.mock.invocationCallOrder[0]);expect(m.prepare.mock.invocationCallOrder[0]).toBeLessThan(m.draft.mock.invocationCallOrder[0]);expect(m.ai).not.toHaveBeenCalled();});
it('upload recovery rejects mismatched reselection without preparing',async()=>{seedAdmission();render(ui());fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));const file=new File(['y'],'Synthetic.pdf',{type:'application/pdf'});fireEvent.change(screen.getByLabelText('Choose document files'),{target:{files:[file]}});await waitFor(()=>expect(screen.getByRole('button',{name:'Remove Synthetic.pdf'})).toBeTruthy());await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));fireEvent.click(screen.getByRole('button',{name:'Recover retained batch'}));await waitFor(()=>expect(screen.getByText(/Reselect the exact original/)).toBeTruthy());expect(m.upload).not.toHaveBeenCalled();expect(m.prepare).not.toHaveBeenCalled();});
it.each(['none','retained'])('historical NULL classification uses only %s original numbered pair',async kind=>{seedAdmission();m.read.mockImplementation(async()=>({success:true,receipt,recovery:{...anchors(),members:[{position:0,upload_session_id:17,session_code:code,kind:'historical',draft_operation_id:null}]}}));if(kind==='retained')(m.store as ReturnType<typeof createWorkspaceDraftStore>).setDraft('draft:tab:owner:f06-batch-drafts:inbox:all',{attempts:JSON.stringify({'17':{input:{uploadSessionId:17,allowDuplicate:false,prepared:snapshot},contract:{operationId:operation,revision:null}}})});render(ui());await recover();await waitFor(()=>expect((screen.getByRole('button',{name:'Recover retained batch'}) as HTMLButtonElement).disabled).toBe(false));if(kind==='retained'){expect(m.draft.mock.calls[0]).toEqual([{uploadSessionId:17,allowDuplicate:false,prepared:snapshot},{operationId:operation,revision:null}]);}else{expect(m.draft).not.toHaveBeenCalled();expect(screen.getByText(/Historical draft processing/)).toBeTruthy();}expect(m.member).not.toHaveBeenCalled();expect(m.prepare).not.toHaveBeenCalled();});
