function changedGraph(original:BatchReceipt):BatchReceipt{return {...original,batch_id:188,batch_code:'B'+'D'.repeat(32),company_id:120,branch_id:121,members:original.members.map(m=>({...m,id:m.id+100,code:'D'.repeat(32),path:'sessions/'+'D'.repeat(32)+'/'+m.name}))};}
function graphRecovery(r:BatchReceipt){return {version:1,admission_operation_id:r.operation_id,admission_fingerprint:r.fingerprint,auth_user_id:r.auth_user_id,profile_id:r.profile_id,batch_id:r.batch_id,owning_company_id:r.company_id,owning_branch_id:r.branch_id,members:r.members.map(m=>({position:m.position,upload_session_id:m.id,session_code:m.code,kind:'unprepared',draft_operation_id:operation,request:{uploadSessionId:m.id,allowDuplicate:false}}))};}
