it('selected retry preserves confirmed siblings for the identical receipt without replaying them',async()=>{const members=seedMulti();const governed=members.map((m,p)=>({...m,kind:'prepared' as const,request:{uploadSessionId:17+p,allowDuplicate:false as const,prepared:{...snapshot,upload_session_id:17+p,session_code:receipt.members[p].code}}}));m.read.mockImplementation(async()=>({success:true,receipt,recovery:{...anchors(),members:governed}}));let lost=true;m.draft.mockImplementation(async(i:BatchDraftInput,c:WorkspaceSaveContract)=>{if(i.uploadSessionId===18&&lost){lost=false;throw Error('lost');}return {success:true,data:{documentId:100+i.uploadSessionId,documentNo:'DMS-'+i.uploadSessionId,status:'pending_ai_review',confidence:'high',operation_id:c.operationId,upload_session_id:i.uploadSessionId,replayed:false}};});render(ui());await recover();await waitFor(()=>expect(screen.getByText('2 of 3 drafts confirmed')).toBeTruthy());await waitFor(()=>expect((screen.getByRole('button',{name:'Retry draft #18'}) as HTMLButtonElement).disabled).toBe(false));const pair=structuredClone(m.draft.mock.calls[1]);fireEvent.click(screen.getByRole('button',{name:'Retry draft #18'}));await waitFor(()=>expect(screen.getByText('3 of 3 drafts confirmed')).toBeTruthy());expect(m.draft.mock.calls.map(c=>c[0].uploadSessionId)).toEqual([17,18,19,18]);expect(m.draft.mock.calls[3]).toEqual(pair);expect(screen.getByRole('button',{name:'Start another batch'})).toBeTruthy();expect(m.upload).not.toHaveBeenCalled();});
it('retired File change cannot reset the replacement input after its await',async()=>{let finish!:(v:ArrayBuffer)=>void;const callback=vi.fn();const file=new File(['x'],'Synthetic.pdf',{type:'application/pdf'});Object.defineProperty(file,'arrayBuffer',{value:()=>new Promise(r=>{finish=r;})});const h=render(<DmsUploadDropzone multiple ownerGeneration="A" onFilesSelected={callback}/>);const input=screen.getByLabelText('Choose document files') as HTMLInputElement;const resets=vi.spyOn(input,'value','set');fireEvent.change(input,{target:{files:[file]}});h.rerender(<DmsUploadDropzone multiple ownerGeneration="B" onFilesSelected={callback}/>);const prior=resets.mock.calls.length;await act(async()=>finish(new Uint8Array([120]).buffer));expect(resets).toHaveBeenCalledTimes(prior);expect(callback).not.toHaveBeenCalled();});
it.each(['','application/octet-stream'])('real generic-MIME %s upload uses original File bytes in canonical transport Blob',async mime=>{render(ui());fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));const file=new File(['x'],'Synthetic.pdf',{type:mime});const slice=vi.spyOn(file,'slice');fireEvent.change(screen.getByLabelText('Choose document files'),{target:{files:[file]}});await waitFor(()=>expect((screen.getByRole('button',{name:'Upload & AI Fill All (1)'}) as HTMLButtonElement).disabled).toBe(false));fireEvent.click(screen.getByRole('button',{name:'Upload & AI Fill All (1)'}));await waitFor(()=>expect(m.upload).toHaveBeenCalledOnce());expect(slice).toHaveBeenCalledWith(0,1,'application/pdf');const [path,token,body,options]=m.upload.mock.calls[0];expect(body).toBe(slice.mock.results[0].value);expect(body.type).toBe('application/pdf');expect(body.size).toBe(1);expect(Array.from(new Uint8Array(await body.arrayBuffer()))).toEqual(Array.from(new Uint8Array(await file.arrayBuffer())));expect(file.name).toBe('Synthetic.pdf');expect(file.type).toBe(mime);expect(path).toBe('sessions/'+code+'/Synthetic.pdf');expect(token).toBe('synthetic-test-value');expect(options).toEqual({contentType:'application/pdf',upsert:false});expect(m.batch.mock.calls[0][0].manifest.files[0].original_filename).toBe(file.name);});
it('same-object read-owner retirement hides owned Files and receipt labels on rerender',async()=>{let live=true;m.readOwner={identity:{authUserId:auth,scopeVersion:'scope'},generation:0,isLive:()=>live,admits:()=>live};const h=render(ui());m.draft.mockRejectedValueOnce(Error('lost'));await start();await waitFor(()=>expect(m.error).toHaveBeenCalled());expect(screen.getByRole('button',{name:'Remove Synthetic.pdf'})).toBeTruthy();expect(screen.getByText('0 of 1 drafts confirmed')).toBeTruthy();live=false;h.rerender(ui());expect(screen.queryByRole('button',{name:'Remove Synthetic.pdf'})).toBeNull();expect(screen.queryByText('0 of 1 drafts confirmed')).toBeNull();expect(screen.queryByRole('button',{name:'Open batch queue'})).toBeNull();expect(screen.getByRole('alert').textContent).toMatch(/owner/);});
it('a current explicit recovery failure focuses its safe summary once work settles',async()=>{seedAdmission();m.read.mockResolvedValue({success:false,code:'unavailable',uncertain:false,error:'PRIVATE denied'});render(ui());await recover();await waitFor(()=>expect(document.activeElement).toBe(screen.getByRole('alert')));expect(screen.getByRole('alert').textContent).not.toContain('PRIVATE');expect(screen.getByRole('alert').getAttribute('tabindex')).toBe('-1');});
it('retired recovery failure cannot focus any new owner summary',async()=>{seedAdmission();let finish!:(v:unknown)=>void;m.read.mockImplementationOnce(()=>new Promise(r=>{finish=r;}));const h=render(ui());await recover();await waitFor(()=>expect(m.read).toHaveBeenCalledOnce());m.owner='B';h.rerender(ui());const focus=vi.spyOn(HTMLElement.prototype,'focus');await act(async()=>finish({success:false,code:'unavailable',uncertain:false,error:'PRIVATE denied'}));expect(focus).not.toHaveBeenCalled();expect(document.body.textContent).not.toContain('PRIVATE');});
it('single-file caller rechecks ownership after the helper resolves, before publishing',async()=>{const callback=vi.fn();const h=render(<DmsUploadDropzone onFileSelected={callback}/>);const digest=vi.spyOn(webcrypto.subtle,'digest');digest.mockImplementationOnce(()=>Promise.resolve(new Uint8Array(32).buffer).then(value=>{queueMicrotask(()=>queueMicrotask(()=>h.unmount()));return value;}));await act(async()=>fireEvent.change(screen.getByLabelText('Choose document file'),{target:{files:[new File(['x'],'Synthetic.pdf',{type:'application/pdf'})]}}));expect(digest).toHaveBeenCalledOnce();expect(callback).not.toHaveBeenCalled();});

it.each(['same-object','replacement'])('validation filenames disappear after %s owner retirement',async kind=>{
 let live=true;
 m.readOwner={identity:{authUserId:auth,scopeVersion:'scope'},generation:0,isLive:()=>live,admits:()=>live};
 const h=render(ui());
 fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));
 await waitFor(()=>expect((screen.getByRole('button',{name:'Find recent admissions'}) as HTMLButtonElement).disabled).toBe(false));
 fireEvent.change(screen.getByLabelText('Choose document files'),{target:{files:[new File(['x'],'Private-owner-A.exe'),new File(['x'],'Synthetic.pdf',{type:'application/pdf'})]}});
 await waitFor(()=>expect(screen.getByRole('button',{name:'Remove Synthetic.pdf'})).toBeTruthy());
 expect(screen.getByRole('alert').textContent).toContain('Private-owner-A.exe');
 const focus=vi.spyOn(HTMLElement.prototype,'focus');
 live=false;
 if(kind==='replacement')m.readOwner={identity:{authUserId:auth,scopeVersion:'scope2'},generation:1,isLive:()=>true,admits:()=>true};
 h.rerender(ui());
 expect(document.body.textContent).not.toContain('Private-owner-A.exe');
 expect(screen.queryByRole('button',{name:'Remove Synthetic.pdf'})).toBeNull();
 expect(focus).not.toHaveBeenCalled();
 for(const fn of [m.batch,m.read,m.member,m.upload,m.prepare,m.draft,m.ai,m.push])expect(fn).not.toHaveBeenCalled();
});

it('single-file validation survives busy changes but never revives after owner A to B to A',async()=>{
 const callback=vi.fn();
 const h=render(<DmsUploadDropzone ownerGeneration="A" onFileSelected={callback}/>);
 fireEvent.change(screen.getByLabelText('Choose document file'),{target:{files:[new File(['x'],'Invalid.exe')]}});
 expect(screen.getByRole('alert').textContent).toContain("'.exe'");
 h.rerender(<DmsUploadDropzone ownerGeneration="A" disabled onFileSelected={callback}/>);
 expect(screen.getByRole('alert').textContent).toContain("'.exe'");
 h.rerender(<DmsUploadDropzone ownerGeneration="A" onFileSelected={callback}/>);
 expect(screen.getByRole('alert').textContent).toContain("'.exe'");
 h.rerender(<DmsUploadDropzone ownerGeneration="B" onFileSelected={callback}/>);
 expect(screen.queryByRole('alert')).toBeNull();
 h.rerender(<DmsUploadDropzone ownerGeneration="A" onFileSelected={callback}/>);
 expect(screen.queryByRole('alert')).toBeNull();
 expect(callback).not.toHaveBeenCalled();
});

function seedPendingLabels(){
 seedAdmission(true);
 const pair={input:{uploadSessionId:17,allowDuplicate:false,prepared:snapshot},contract:{operationId:operation,revision:null},uncertain:true};
 const raw=JSON.stringify({'17':pair,'99':{input:{uploadSessionId:99,allowDuplicate:false},contract:{operationId:'99999999-9999-4999-8999-999999999999',revision:null},uncertain:true}});
 const store=m.store as ReturnType<typeof createWorkspaceDraftStore>;
 store.setDraft('draft:tab:owner:f06-batch-drafts:inbox:all',{attempts:raw});
 return {store,raw,pair,admission:store.getDraft('draft:tab:owner:f06-batch-admission:inbox:all')};
}

it('pending retry labels wait for rebind and include only the current admission members',async()=>{
 const {store,raw,pair,admission}=seedPendingLabels();
 const clear=vi.spyOn(store,'clearDraft');
 let finish!:(value:unknown)=>void;
 m.bootstrap.mockImplementationOnce(()=>new Promise(resolve=>{finish=resolve;}));
 render(ui());
 fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));
 await waitFor(()=>expect(m.bootstrap).toHaveBeenCalledOnce());
 expect(screen.queryAllByRole('button',{name:/Retry draft #/})).toHaveLength(0);
 expect(store.getDraft('draft:tab:owner:f06-batch-drafts:inbox:all')?.attempts).toBe(raw);
 await act(async()=>finish({success:true,origin:{authUserId:auth,profileId:7}}));
 await waitFor(()=>expect((screen.getByRole('button',{name:'Retry draft #17'}) as HTMLButtonElement).disabled).toBe(false));
 expect(screen.queryByRole('button',{name:'Retry draft #99'})).toBeNull();
 expect(store.getDraft('draft:tab:owner:f06-batch-drafts:inbox:all')?.attempts).toBe(raw);
 expect(store.getDraft('draft:tab:owner:f06-batch-admission:inbox:all')).toEqual(admission);
 expect(clear).not.toHaveBeenCalled();
 fireEvent.click(screen.getByRole('button',{name:'Retry draft #17'}));
 await waitFor(()=>expect(m.success).toHaveBeenCalledOnce());
 expect(m.draft).toHaveBeenCalledExactlyOnceWith(pair.input,pair.contract);
 for(const fn of [m.batch,m.member,m.upload,m.verify,m.prepare,m.ai])expect(fn).not.toHaveBeenCalled();
 expect(JSON.parse(store.getDraft('draft:tab:owner:f06-batch-drafts:inbox:all')!.attempts!)['99']).toEqual(JSON.parse(raw)['99']);
 expect(clear).not.toHaveBeenCalled();
});

it('same-object retirement hides pending retry labels and fresh owner rebind restores the exact pair',async()=>{
 const {store,raw,pair,admission}=seedPendingLabels();
 const clear=vi.spyOn(store,'clearDraft');
 let live=true;
 m.readOwner={identity:{authUserId:auth,scopeVersion:'scope'},generation:0,isLive:()=>live,admits:()=>live};
 const h=render(ui());
 fireEvent.click(screen.getByRole('button',{name:'Multiple Files (Batch)'}));
 await waitFor(()=>expect((screen.getByRole('button',{name:'Retry draft #17'}) as HTMLButtonElement).disabled).toBe(false));
 const focus=vi.spyOn(HTMLElement.prototype,'focus');
 live=false;
 h.rerender(ui());
 expect(screen.queryAllByRole('button',{name:/Retry draft #/})).toHaveLength(0);
 let finish!:(value:unknown)=>void;
 m.bootstrap.mockImplementationOnce(()=>new Promise(resolve=>{finish=resolve;}));
 m.readOwner={identity:{authUserId:auth,scopeVersion:'scope2'},generation:1,isLive:()=>true,admits:()=>true};
 h.rerender(ui());
 expect(screen.queryAllByRole('button',{name:/Retry draft #/})).toHaveLength(0);
 expect(store.getDraft('draft:tab:owner:f06-batch-drafts:inbox:all')?.attempts).toBe(raw);
 expect(store.getDraft('draft:tab:owner:f06-batch-admission:inbox:all')).toEqual(admission);
 await act(async()=>finish({success:true,origin:{authUserId:auth,profileId:7}}));
 await waitFor(()=>expect((screen.getByRole('button',{name:'Retry draft #17'}) as HTMLButtonElement).disabled).toBe(false));
 expect(screen.queryByRole('button',{name:'Retry draft #99'})).toBeNull();
 expect(m.draft).not.toHaveBeenCalled();
 expect(focus).not.toHaveBeenCalled();
 expect(clear).not.toHaveBeenCalled();
 fireEvent.click(screen.getByRole('button',{name:'Retry draft #17'}));
 await waitFor(()=>expect(m.success).toHaveBeenCalledOnce());
 expect(m.draft).toHaveBeenCalledExactlyOnceWith(pair.input,pair.contract);
 for(const fn of [m.batch,m.member,m.upload,m.verify,m.prepare,m.ai])expect(fn).not.toHaveBeenCalled();
 expect(clear).not.toHaveBeenCalled();
});
